window.MiniTabs=function(){function t(t){var e=t.querySelectorAll("[data-tab]");e.forEach(function(n){n.addEventListener("click",function(){e.forEach(function(e){e.classList.toggle("active",e===n),t.querySelector("#"+e.dataset.tab).hidden=e!==n})})})}return{init:function(){document.querySelectorAll("[data-tabs]").forEach(t)}}}();
